"use client";
import { FormEvent, useState } from "react";
import { FileUp, Send } from "lucide-react";
export default function VendorResponse() {
  const [message, setMessage] = useState(""); const [files, setFiles] = useState<File[]>([]); const [status, setStatus] = useState("");
  async function submit(event: FormEvent) { event.preventDefault(); setStatus("Reading response…"); const data = new FormData(); data.append("message", message); files.forEach((file) => data.append("files", file)); const response = await fetch("/api/extract", { method: "POST", body: data }); const payload = await response.json(); setStatus(response.ok ? `Received — ${payload.extraction.lineQuotes?.length ?? 0} quote lines extracted for buyer review.` : payload.error); }
  return <main className="vendor-shell"><header className="vendor-header"><b>RFX Pilot</b><span>Secure vendor response</span></header><section className="vendor-content"><div className="eyebrow">SUPPLIER RESPONSE</div><h1>Respond in your own format.</h1><p className="subcopy">FY27 Corrugated Packaging Sourcing · Bengaluru manufacturing plant</p><p className="vendor-note">Attach your usual quote files and/or enter a message. No template is required.</p><form onSubmit={submit} className="response-form"><label>Message to buyer<textarea value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Pricing notes, freight, terms, or other context" rows={5} /></label><label>Attachments <div className="dropzone"><FileUp /><input type="file" multiple accept=".xlsx,.xls,.csv,.pdf,.docx,.png,.jpg,.jpeg" onChange={(e) => setFiles(Array.from(e.target.files || []))} /><small>{files.length ? files.map((f) => f.name).join(", ") : "XLSX, XLS, CSV, PDF, DOCX, PNG, JPG"}</small></div></label><button className="submit-response" disabled={(!message && !files.length) || status === "Reading response…"}><Send size={16} /> Submit response</button>{status && <p className="form-status">{status}</p>}</form></section></main>;
}
